{
  "name": "高效液相色谱输液泵",
  "name_en": "HPLC pump",
  "manufacturer": "",
  "description": "这是一种用于高效液相色谱等实验系统的高压输液泵，用于以稳定且可控的流量输送流动相。设备可设定流速、监测压力、设置压力保护限值，并可结合溶剂压缩性参数进行补偿，适用于分析化学中的连续溶剂输送与分离实验。",
  "description_en": "This is a high-pressure liquid chromatography pump used to deliver mobile phase at a stable, controlled flow rate in HPLC and related laboratory systems. It supports flow-rate setting, pressure monitoring, pressure limit protection, and solvent compressibility compensation for continuous solvent delivery in analytical separations.",
  "tag_hints": [
    "HPLC solvent delivery",
    "high-pressure liquid chromatography",
    "flow rate control",
    "pressure monitoring",
    "pressure limit protection",
    "solvent compressibility compensation",
    "leak detection"
  ],
  "actions": [
    {
      "action_name": "auto-run",
      "description": "启动泵运行",
      "description_en": "start the pump"
    },
    {
      "action_name": "auto-stop",
      "description": "停止泵运行",
      "description_en": "stop the pump"
    },
    {
      "action_name": "auto-keypad_enable",
      "description": "启用设备面板按键",
      "description_en": "enable the device keypad"
    },
    {
      "action_name": "auto-keypad_disable",
      "description": "禁用设备面板按键",
      "description_en": "disable the device keypad"
    },
    {
      "action_name": "auto-clear_faults",
      "description": "清除故障状态",
      "description_en": "clear fault states"
    },
    {
      "action_name": "auto-reset",
      "description": "将用户可调参数恢复为出厂默认值",
      "description_en": "reset user-adjustable settings to factory defaults"
    },
    {
      "action_name": "auto-zero_seal",
      "description": "将密封寿命冲程计数器清零",
      "description_en": "zero the seal-life stroke counter"
    },
    {
      "action_name": "auto-current_conditions",
      "description": "获取当前压力和流量",
      "description_en": "get the current pressure and flow rate"
    },
    {
      "action_name": "auto-current_state",
      "description": "获取当前运行状态和压力限值",
      "description_en": "get the current operating state and pressure limits"
    },
    {
      "action_name": "auto-pump_info",
      "description": "获取泵的综合信息与状态",
      "description_en": "get overall pump information and status"
    },
    {
      "action_name": "auto-read_faults",
      "description": "获取当前故障状态",
      "description_en": "get the current fault status"
    },
    {
      "action_name": "auto-flowrate_compensation",
      "description": "获取/设置流量补偿系数",
      "description_en": "get/set the flow rate compensation factor"
    },
    {
      "action_name": "auto-flowrate",
      "description": "获取/设置流量",
      "description_en": "get/set the flow rate"
    },
    {
      "action_name": "auto-upper_pressure_limit",
      "description": "获取/设置上限压力",
      "description_en": "get/set the upper pressure limit"
    },
    {
      "action_name": "auto-lower_pressure_limit",
      "description": "获取/设置下限压力",
      "description_en": "get/set the lower pressure limit"
    },
    {
      "action_name": "auto-set_leak_mode",
      "description": "设置泄漏检测处理模式",
      "description_en": "set the leak handling mode"
    },
    {
      "action_name": "auto-solvent",
      "description": "获取/设置溶剂压缩性参数",
      "description_en": "get/set the solvent compressibility value"
    }
  ]
}

